1:'use strict';
2:const test = require('node:test');
3:const assert = require('node:assert/strict');
4:const { createParser, parse } = require('../src/csv');
5:
6:test('single push emits complete comma-separated records', () => {
7:  const parser = createParser();
8:  assert.deepEqual(parser.push('name,age\nAda,37\n'), [['name', 'age'], ['Ada', '37']]);
9:  assert.deepEqual(parser.end(), []);
10:});
11:
12:test('single push parses quoted commas and doubled quotes', () => {
13:  assert.deepEqual(parse('"a,b","say ""hi"""\n'), [['a,b', 'say "hi"']]);
14:});
15:
16:test('end flushes one unfinished record including empty fields', () => {
17:  const parser = createParser();
18:  assert.deepEqual(parser.push('left,,right,'), []);
19:  assert.deepEqual(parser.end(), [['left', '', 'right', '']]);
20:});
21:
22:test('single push preserves a newline inside a quoted field', () => {
23:  assert.deepEqual(parse('"first\nsecond",tail\n'), [['first\nsecond', 'tail']]);
24:});
25:
26:test('parse header mode uses the first record as object keys', () => {
27:  assert.deepEqual(parse('name,age\nAda,37\n', { header: true }), [{ name: 'Ada', age: '37' }]);
28:});

