'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

function allSplits(text, opts) {
  const whole = parse(text, opts);
  for (let a = 0; a <= text.length; a++) {
    for (let b = a; b <= text.length; b++) {
      const p = createParser(opts);
      const r = [...p.push(text.slice(0, a)), ...p.push(''), ...p.push(text.slice(a, b)), ...p.push(text.slice(b)), ...p.end()];
      assert.deepEqual(r, whole, JSON.stringify([text, a, b]));
    }
  }
  return whole;
}
function errLine(text) {
  for (let a = 0; a <= text.length; a++) {
    const p = createParser();
    try { p.push(text.slice(0, a)); p.push(text.slice(a)); p.end(); } catch (e) {
      assert(e instanceof SyntaxError); const m = /line (\d+)/.exec(e.message); assert(m, e.message);
      if (a === 0) var first = m[1]; else assert.equal(m[1], first, JSON.stringify([text, a]));
      continue;
    }
    assert.fail('no error ' + JSON.stringify(text));
  }
  return Number(first);
}

assert.deepEqual(allSplits(''), []);
assert.deepEqual(allSplits('\uFEFF'), []);
assert.deepEqual(allSplits('\n'), [['']]);
assert.deepEqual(allSplits('\n\n'), [[''], ['']]);
assert.deepEqual(allSplits('a\r\nb\rc\n'), [['a'], ['b'], ['c']]);
assert.deepEqual(allSplits('a\r\n\r\nb'), [['a'], [''], ['b']]);
assert.deepEqual(allSplits('\uFEFFa,\uFEFF'), [['a', '\uFEFF']]);
assert.deepEqual(allSplits('a"b,"c""d",""\r\n'), [['a"b', 'c"d', '']]);
assert.deepEqual(allSplits('"x\r\ny\rz\n",1'), [['x\r\ny\rz\n', '1']]);
assert.deepEqual(allSplits('a;b,c\n', { delimiter: ';' }), [['a', 'b,c']]);
assert.deepEqual(allSplits('"",\r'), [['', '']]);
assert.deepEqual(allSplits('😀,é'), [['😀', 'é']]);
assert.equal(errLine('"a" ,b'), 1);
assert.equal(errLine('x\r\n"a\r\nb"c'), 3);
assert.equal(errLine('x\r\r\n\n"a'), 4);
assert.equal(errLine('"a\n'), 2);

// first-chunk eager emission even with pending CRLF
const p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), Error);
const q = createParser();
assert.deepEqual(q.push(''), []);
assert.deepEqual(q.push('\uFEFFz'), []);
assert.deepEqual(q.end(), [['z']]);
assert.throws(() => createParser().push(1), TypeError);
for (const d of ['"', '\r', '\n', '', ',,', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);
assert.deepEqual(createParser({ delimiter: undefined }).push('a,b\n'), [['a', 'b']]);
assert.deepEqual(createParser({ header: true }).push('a\n'), [['a']]);
assert.deepEqual(parse('', { header: true }), []);
assert.deepEqual(parse('x,x,x_2,x\n1,2,3\n', { header: true }), [{ x: '1', x_2: '2', x_2_2: '3', x_3: '' }]);
