  }

  let state = FIELD_START;
  let field = '';
  let fields = [];
  let line = 1;
  let prevCR = false; // previous character was CR (for CRLF line counting)
  let skipLF = false; // an outside-quote CR ended a record; swallow a following LF
  let seenInput = false;
  let ended = false;

  function endRecord(out) {
    fields.push(field);
    out.push(fields);
    fields = [];
    field = '';
    state = FIELD_START;
  }

  function push(chunk) {
    if (ended) throw new Error('push() called after end()');
    if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
